const fs = require('fs');
const path = require('path');
const { compileFromFile } = require('json-schema-to-typescript');

const SCHEMA_DIR = path.join(__dirname, '../../schema');
const OUTPUT_DIR = path.join(__dirname, '../src/app/models/generated');

const BANNER_COMMENT = `/* eslint-disable */
/**
 * This file was automatically generated by json-schema-to-typescript.
 * DO NOT MODIFY IT BY HAND. Instead, modify the source JSON Schema file,
 * and run 'npm run generate:schema-types' to regenerate this file.
 */`;

async function generateTypes() {
  if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  }

  const schemaPath = path.join(SCHEMA_DIR, 'flagd-schema.json');

  try {
    const mainSchemaStr = fs.readFileSync(schemaPath, 'utf8');

    let mainSchema = JSON.parse(mainSchemaStr);

    // Resolve top-level $ref reference only
    console.log('Resolving top-level $ref reference...');
    if (
      mainSchema.$ref &&
      typeof mainSchema.$ref === 'string' &&
      mainSchema.$ref.startsWith('#/definitions/')
    ) {
      const refPath = mainSchema.$ref.replace('#/definitions/', '');
      const definition = mainSchema.definitions[refPath];

      if (definition) {
        // Create a new mainSchema with the $ref replaced by the definition content
        delete mainSchema.$ref;
        delete mainSchema.definitions[refPath];

        // Deep clone the definition
        const resolvedDefinition = JSON.parse(JSON.stringify(definition));

        // Merge: definition properties take precedence, but keep other top-level properties
        mainSchema = {
          ...resolvedDefinition,
          ...mainSchema,
        };
      } else {
        throw new Error(`Reference "${mainSchema.$ref}" not found in definitions.`);
      }
    }

    delete mainSchema.$id;
    delete mainSchema.$schema;

    // Write modified schema to temp file so compileFromFile can resolve relative $refs
    const tempSchemaPath = path.join(SCHEMA_DIR, '.flagd-schema.temp.json');
    fs.writeFileSync(tempSchemaPath, JSON.stringify(mainSchema));

    try {
      const targetingTypes = await compileFromFile(tempSchemaPath, {
        cwd: SCHEMA_DIR,
        bannerComment: BANNER_COMMENT,
        strictIndexSignatures: true,
        style: { singleQuote: true },
      });

      fs.writeFileSync(path.join(OUTPUT_DIR, 'flagd-schema.ts'), targetingTypes);
      console.log('✓ Generated flagd-schema.ts');
    } finally {
      // Clean up temp file
      fs.unlinkSync(tempSchemaPath);
    }
  } catch (err) {
    console.error('Error dereferencing schema:', err);
    process.exit(1);
  }
}

generateTypes();
